@Composable
fun SignUpScreen(
    viewModel: AuthViewModel,
    onSignUpSuccess: () -> Unit,
    onNavigateToLogin: () -> Unit
) {
    val uiState by viewModel.uiState.collectAsStateWithLifecycle()
    var email by remember { mutableStateOf("") }
    var password by remember { mutableStateOf("") }
    var confirmPassword by remember { mutableStateOf("") }
    var passwordVisible by remember { mutableStateOf(false) }
    var confirmPasswordVisible by remember { mutableStateOf(false) }
    val snackbarHostState = remember { SnackbarHostState() }

    LaunchedEffect(uiState.authUser) {
        if (uiState.authUser != null && !uiState.isLoading) {
            onSignUpSuccess()
        }
    }

    LaunchedEffect(uiState.error) {
        if (uiState.error != null) {
            snackbarHostState.showSnackbar(uiState.error!!)
            viewModel.clearError()
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(MaterialTheme.colorScheme.surface)
    ) {
        Box(
            modifier = Modifier
                .align(Alignment.TopEnd)
                .size(200.dp)
                .background(
                    MaterialTheme.colorScheme.primary.copy(alpha = 0.1f),
                    shape = CircleShape
                )
        )

        Column(
            modifier = Modifier
                .fillMaxSize()
                .verticalScroll(rememberScrollState())
                .padding(24.dp),
            horizontalAlignment = Alignment.Start,
            verticalArrangement = Arrangement.Top
        ) {
            IconButton(
                onClick = onNavigateToLogin,
                modifier = Modifier.size(40.dp)
            ) {
                Icon(
                    Icons.Filled.ArrowBack,
                    contentDescription = "Back",
                    tint = MaterialTheme.colorScheme.onSurface
                )
            }

            Spacer(modifier = Modifier.height(24.dp))

            Text(
                text = "Sign up",
                style = MaterialTheme.typography.displaySmall,
                color = MaterialTheme.colorScheme.onSurface
            )

            Text(
                text = "your account",
                style = MaterialTheme.typography.bodyLarge,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )

            Spacer(modifier = Modifier.height(32.dp))

            OutlinedTextField(
                value = email,
                onValueChange = { email = it },
                label = { Text("Email") },
                leadingIcon = { Icon(Icons.Filled.Email, contentDescription = "Email") },
                modifier = Modifier.fillMaxWidth(),
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Email),
                enabled = !uiState.isLoading,
                colors = OutlinedTextFieldDefaults.colors(
                    focusedBorderColor = MaterialTheme.colorScheme.primary,
                    unfocusedBorderColor = MaterialTheme.colorScheme.outlineVariant
                )
            )

            Spacer(modifier = Modifier.height(16.dp))

            OutlinedTextField(
                value = password,
                onValueChange = { password = it },
                label = { Text("Password") },
                leadingIcon = { Icon(Icons.Filled.Lock, contentDescription = "Password") },
                trailingIcon = {
                    IconButton(onClick = { passwordVisible = !passwordVisible }) {
                        Icon(
                            if (passwordVisible) Icons.Filled.Visibility else Icons.Filled.VisibilityOff,
                            contentDescription = "Toggle password visibility"
                        )
                    }
                },
                visualTransformation = if (passwordVisible) VisualTransformation.None else PasswordVisualTransformation(),
                modifier = Modifier.fillMaxWidth(),
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Password),
                enabled = !uiState.isLoading,
                colors = OutlinedTextFieldDefaults.colors(
                    focusedBorderColor = MaterialTheme.colorScheme.primary,
                    unfocusedBorderColor = MaterialTheme.colorScheme.outlineVariant
                )
            )

            Spacer(modifier = Modifier.height(16.dp))

            OutlinedTextField(
                value = confirmPassword,
                onValueChange = { confirmPassword = it },
                label = { Text("Confirm Password") },
                leadingIcon = { Icon(Icons.Filled.Lock, contentDescription = "Confirm Password") },
                trailingIcon = {
                    IconButton(onClick = { confirmPasswordVisible = !confirmPasswordVisible }) {
                        Icon(
                            if (confirmPasswordVisible) Icons.Filled.Visibility else Icons.Filled.VisibilityOff,
                            contentDescription = "Toggle password visibility"
                        )
                    }
                },
                visualTransformation = if (confirmPasswordVisible) VisualTransformation.None else PasswordVisualTransformation(),
                modifier = Modifier.fillMaxWidth(),
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Password),
                enabled = !uiState.isLoading,
                colors = OutlinedTextFieldDefaults.colors(
                    focusedBorderColor = MaterialTheme.colorScheme.primary,
                    unfocusedBorderColor = MaterialTheme.colorScheme.outlineVariant
                )
            )

            Spacer(modifier = Modifier.height(32.dp))

            Button(
                onClick = { viewModel.signUp(email, password, confirmPassword) },
                modifier = Modifier
                    .fillMaxWidth()
                    .height(48.dp),
                enabled = !uiState.isLoading && email.isNotBlank() && password.isNotBlank() && confirmPassword.isNotBlank(),
                colors = ButtonDefaults.buttonColors(
                    containerColor = MaterialTheme.colorScheme.primary
                ),
                shape = MaterialTheme.shapes.medium
            ) {
                Text(
                    if (uiState.isLoading) "Creating Account..." else "Sign Up",
                    style = MaterialTheme.typography.labelLarge
                )
            }

            Spacer(modifier = Modifier.height(24.dp))

            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.Center
            ) {
                Text("Already have an account? ")
                TextButton(onClick = onNavigateToLogin) {
                    Text("Sign In")
                }
            }
        }

        SnackbarHost(
            hostState = snackbarHostState,
            modifier = Modifier.align(Alignment.BottomCenter)
        ) {
            Snackbar(
                modifier = Modifier.padding(16.dp),
                action = {
                    TextButton(onClick = { snackbarHostState.currentSnackbarData?.dismiss() }) {
                        Text("Dismiss")
                    }
                }
            ) {
                Text(it.visuals.message)
            }
        }
    }
}

package com.cloudsbay.brewbyadarsh.core

import android.util.Log
import androidx.datastore.core.DataStore
import androidx.datastore.preferences.core.Preferences
import androidx.datastore.preferences.core.edit
import androidx.datastore.preferences.core.stringPreferencesKey
import com.cloudsbay.brewbyadarsh.features.auth.domain.models.AuthSession
import com.cloudsbay.brewbyadarsh.features.auth.domain.models.AuthUser
import io.github.jan.supabase.auth.user.UserSession
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.map
import kotlinx.serialization.json.Json
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class SessionManager @Inject constructor(
    private val dataStore: DataStore<Preferences>,
    private val json: Json,
) : io.github.jan.supabase.auth.SessionManager {
    companion object {
        private const val TAG = "SessionManager"
        private val AUTH_SESSION_KEY = stringPreferencesKey("auth_session")
        private val SUPABASE_SESSION_KEY = stringPreferencesKey("supabase_session")
    }

    override suspend fun saveSession(session: UserSession) {
        Log.d(TAG, "Saving session for user: ${session.user?.id}")
        dataStore.edit { preferences ->
            preferences[SUPABASE_SESSION_KEY] = json.encodeToString(session)

            // Map UserSession to our domain AuthSession
            val authUser = AuthUser(
                id = session.user?.id ?: "",
                email = session.user?.email,
                phone = session.user?.phone,
                emailConfirmedAt = session.user?.emailConfirmedAt?.toString(),
                phoneConfirmedAt = session.user?.phoneConfirmedAt?.toString(),
                lastSignInAt = session.user?.lastSignInAt?.toString(),
                userMetadata = session.user?.userMetadata?.mapValues { it.value.toString() },
                appMetadata = session.user?.appMetadata?.mapValues { it.value.toString() },
            )
            val authSession = AuthSession(
                accessToken = session.accessToken,
                refreshToken = session.refreshToken,
                user = authUser,
                expiresAt = session.expiresAt.toEpochMilliseconds()
            )
            preferences[AUTH_SESSION_KEY] = json.encodeToString(authSession)
        }
    }

    override suspend fun loadSession(): UserSession {
        Log.d(TAG, "loadSession() called")
        val preferences = dataStore.data.first()
        val sessionJson = preferences[SUPABASE_SESSION_KEY] 
            ?: run {
                Log.w(TAG, "loadSession: No session found in DataStore")
                error("No session found")
            }
        return try {
            json.decodeFromString<UserSession>(sessionJson).also {
                Log.d(TAG, "loadSession: Successfully loaded session for user: ${it.user?.id}")
            }
        } catch (e: Exception) {
            Log.e(TAG, "loadSession: Failed to decode session JSON", e)
            throw e
        }
    }

    override suspend fun loadSessionOrNull(): UserSession? {
        Log.d(TAG, "loadSessionOrNull() called")
        val preferences = dataStore.data.first()
        val sessionJson = preferences[SUPABASE_SESSION_KEY] ?: run {
            Log.d(TAG, "loadSessionOrNull: No session found")
            return null
        }
        return try {
            json.decodeFromString<UserSession>(sessionJson).also {
                Log.d(TAG, "loadSessionOrNull: Successfully loaded session for user: ${it.user?.id}")
            }
        } catch (e: Exception) {
            Log.e(TAG, "loadSessionOrNull: Failed to decode session JSON", e)
            null
        }
    }

    override suspend fun deleteSession() {
        Log.d(TAG, "Deleting session")
        dataStore.edit { preferences ->
            preferences.remove(SUPABASE_SESSION_KEY)
            preferences.remove(AUTH_SESSION_KEY)
        }
    }

    val authSession: Flow<AuthSession?> = dataStore.data.map { preferences ->
        val sessionJson = preferences[AUTH_SESSION_KEY]
        if (sessionJson != null) {
            try {
                json.decodeFromString<AuthSession>(sessionJson)
            } catch (_: Exception) {
                null
            }
        } else {
            null
        }
    }

    val isLoggedIn: Flow<Boolean> = authSession.map { it != null }

    suspend fun saveSession(session: AuthSession) {
        dataStore.edit { preferences ->
            preferences[AUTH_SESSION_KEY] = json.encodeToString(session)
        }
    }

    suspend fun clearSession() {
        deleteSession()
    }
}

package com.cloudsbay.brewbyadarsh.core

import android.util.Log
import androidx.datastore.core.DataStore
import androidx.datastore.preferences.core.Preferences
import androidx.datastore.preferences.core.edit
import androidx.datastore.preferences.core.stringPreferencesKey
import androidx.datastore.preferences.core.booleanPreferencesKey
import com.cloudsbay.brewbyadarsh.features.auth.domain.models.AuthSession
import com.cloudsbay.brewbyadarsh.features.auth.domain.models.AuthUser
import io.github.jan.supabase.auth.user.UserSession
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.map
import kotlinx.serialization.json.Json
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class SessionManager @Inject constructor(
    private val dataStore: DataStore<Preferences>,
    private val json: Json,
) : io.github.jan.supabase.auth.SessionManager {
    companion object {
        private const val TAG = "SessionManager"
        private val AUTH_SESSION_KEY = stringPreferencesKey("auth_session")
        private val SUPABASE_SESSION_KEY = stringPreferencesKey("supabase_session")
        private val PENDING_SIGN_OUT_KEY = booleanPreferencesKey("pending_sign_out")
    }

    override suspend fun saveSession(session: UserSession) {
        Log.d(TAG, "Saving session for user: ${session.user?.id}")
        dataStore.edit { preferences ->
            preferences[SUPABASE_SESSION_KEY] = json.encodeToString(session)

            // Map UserSession to our domain AuthSession
            val authUser = AuthUser(
                id = session.user?.id ?: "",
                email = session.user?.email,
                phone = session.user?.phone,
                emailConfirmedAt = session.user?.emailConfirmedAt?.toString(),
                phoneConfirmedAt = session.user?.phoneConfirmedAt?.toString(),
                lastSignInAt = session.user?.lastSignInAt?.toString(),
                userMetadata = session.user?.userMetadata?.mapValues { it.value.toString() },
                appMetadata = session.user?.appMetadata?.mapValues { it.value.toString() },
            )
            val authSession = AuthSession(
                accessToken = session.accessToken,
                refreshToken = session.refreshToken,
                user = authUser,
                expiresAt = session.expiresAt.toEpochMilliseconds()
            )
            preferences[AUTH_SESSION_KEY] = json.encodeToString(authSession)
        }
    }

    override suspend fun loadSession(): UserSession {
        Log.d(TAG, "loadSession() called")
        val preferences = dataStore.data.first()
        val sessionJson = preferences[SUPABASE_SESSION_KEY] 
            ?: run {
                Log.w(TAG, "loadSession: No session found in DataStore")
                error("No session found")
            }
        return try {
            json.decodeFromString<UserSession>(sessionJson).also {
                Log.d(TAG, "loadSession: Successfully loaded session for user: ${it.user?.id}")
            }
        } catch (e: Exception) {
            Log.e(TAG, "loadSession: Failed to decode session JSON", e)
            throw e
        }
    }

    override suspend fun loadSessionOrNull(): UserSession? {
        Log.d(TAG, "loadSessionOrNull() called")
        val preferences = dataStore.data.first()
        val sessionJson = preferences[SUPABASE_SESSION_KEY] ?: run {
            Log.d(TAG, "loadSessionOrNull: No session found")
            return null
        }
        return try {
            json.decodeFromString<UserSession>(sessionJson).also {
                Log.d(TAG, "loadSessionOrNull: Successfully loaded session for user: ${it.user?.id}")
            }
        } catch (e: Exception) {
            Log.e(TAG, "loadSessionOrNull: Failed to decode session JSON", e)
            null
        }
    }

    override suspend fun deleteSession() {
        Log.d(TAG, "Deleting session")
        dataStore.edit { preferences ->
            preferences.remove(SUPABASE_SESSION_KEY)
            preferences.remove(AUTH_SESSION_KEY)
        }
    }

    suspend fun markPendingSignOut() {
        dataStore.edit { preferences ->
            preferences[PENDING_SIGN_OUT_KEY] = true
        }
    }

    suspend fun clearPendingSignOut() {
        dataStore.edit { preferences ->
            preferences.remove(PENDING_SIGN_OUT_KEY)
        }
    }

    suspend fun isPendingSignOut(): Boolean {
        return dataStore.data.first()[PENDING_SIGN_OUT_KEY] == true
    }

    val authSession: Flow<AuthSession?> = dataStore.data.map { preferences ->
        val sessionJson = preferences[AUTH_SESSION_KEY]
        if (sessionJson != null) {
            try {
                json.decodeFromString<AuthSession>(sessionJson)
            } catch (_: Exception) {
                null
            }
        } else {
            null
        }
    }

    val isLoggedIn: Flow<Boolean> = authSession.map { it != null }

    suspend fun saveSession(session: AuthSession) {
        dataStore.edit { preferences ->
            preferences[AUTH_SESSION_KEY] = json.encodeToString(session)
        }
    }

    suspend fun clearSession() {
        deleteSession()
    }
}

package com.cloudsbay.brewbyadarsh.core.errors

enum class AuthAction {
    SIGN_IN,
    SIGN_UP,
    SIGN_OUT,
    RESET_PASSWORD,
    UPDATE_PASSWORD,
    UPDATE_PROFILE,
    GET_SESSION,
    REFRESH_SESSION,
    VERIFY_OTP,
    RESEND_VERIFICATION
}

object AuthErrorMapper {
    fun map(throwable: Throwable, action: AuthAction): AppError {
        val message = (throwable.message ?: "").lowercase()

        return when {
            message.contains("unable to resolve host") || message.contains("unknownhost") -> {
                AppError(
                    title = titleFor(action),
                    message = "We can't reach the server right now. Check your internet and try again.",
                    isRetryable = true
                )
            }
            message.contains("timeout") || message.contains("timed out") -> {
                AppError(
                    title = titleFor(action),
                    message = "The connection is taking too long. Please try again in a moment.",
                    isRetryable = true
                )
            }
            message.contains("network") || message.contains("connection") -> {
                AppError(
                    title = titleFor(action),
                    message = "Network error. Please check your connection and try again.",
                    isRetryable = true
                )
            }
            message.contains("invalid login credentials") || message.contains("invalid_grant") -> {
                AppError(
                    title = titleFor(action),
                    message = "Email or password is incorrect. Please try again.",
                    isRetryable = true
                )
            }
            message.contains("email") && message.contains("already") -> {
                AppError(
                    title = titleFor(action),
                    message = "This email is already in use. Try signing in instead.",
                    isRetryable = false
                )
            }
            message.contains("user not found") || message.contains("not found") -> {
                AppError(
                    title = titleFor(action),
                    message = "We couldn't find an account with this email.",
                    isRetryable = false
                )
            }
            message.contains("session is null") -> {
                AppError(
                    title = titleFor(action),
                    message = "We couldn't finish signing in. Please try again.",
                    isRetryable = true
                )
            }
            else -> {
                AppError(
                    title = titleFor(action),
                    message = genericMessageFor(action),
                    isRetryable = true
                )
            }
        }
    }

    private fun titleFor(action: AuthAction): String = when (action) {
        AuthAction.SIGN_IN -> "Sign In Failed"
        AuthAction.SIGN_UP -> "Sign Up Failed"
        AuthAction.SIGN_OUT -> "Sign Out Failed"
        AuthAction.RESET_PASSWORD -> "Password Reset Failed"
        AuthAction.UPDATE_PASSWORD -> "Password Update Failed"
        AuthAction.UPDATE_PROFILE -> "Update Failed"
        AuthAction.GET_SESSION -> "Session Error"
        AuthAction.REFRESH_SESSION -> "Session Error"
        AuthAction.VERIFY_OTP -> "Verification Failed"
        AuthAction.RESEND_VERIFICATION -> "Verification Failed"
    }

    private fun genericMessageFor(action: AuthAction): String = when (action) {
        AuthAction.SIGN_IN -> "We couldn't sign you in right now. Please try again."
        AuthAction.SIGN_UP -> "We couldn't create your account right now. Please try again."
        AuthAction.SIGN_OUT -> "We couldn't sign you out right now. Please try again."
        AuthAction.RESET_PASSWORD -> "We couldn't send the reset email. Please try again."
        AuthAction.UPDATE_PASSWORD -> "We couldn't update your password. Please try again."
        AuthAction.UPDATE_PROFILE -> "We couldn't update your profile. Please try again."
        AuthAction.GET_SESSION -> "We couldn't access your session. Please try again."
        AuthAction.REFRESH_SESSION -> "We couldn't refresh your session. Please try again."
        AuthAction.VERIFY_OTP -> "We couldn't verify the code. Please try again."
        AuthAction.RESEND_VERIFICATION -> "We couldn't resend the verification email. Please try again."
    }
}

package com.cloudsbay.brewbyadarsh.core.ui.components

import androidx.compose.material3.AlertDialog
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Text
import androidx.compose.material3.TextButton
import androidx.compose.runtime.Composable
import androidx.compose.ui.text.font.FontWeight

/**
 * Reusable Error Dialog Component for displaying errors and edge cases
 */
@Composable
fun ErrorDialog(
    title: String = "Error",
    message: String,
    onDismiss: () -> Unit,
    confirmButtonText: String = "OK",
    dismissButtonText: String? = null,
    onConfirm: () -> Unit = onDismiss,
    isDismissible: Boolean = true
) {
    AlertDialog(
        onDismissRequest = {
            if (isDismissible) {
                onDismiss()
            }
        },
        title = {
            Text(
                text = title,
                color = MaterialTheme.colorScheme.onSurface,
                fontWeight = FontWeight.Bold
            )
        },
        text = {
            Text(
                text = message,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )
        },
        confirmButton = {
            TextButton(
                onClick = {
                    onConfirm()
                    onDismiss()
                }
            ) {
                Text(
                    text = confirmButtonText,
                    color = MaterialTheme.colorScheme.primary,
                    fontWeight = FontWeight.Bold
                )
            }
        },
        dismissButton = if (dismissButtonText != null) {
            {
                TextButton(
                    onClick = onDismiss
                ) {
                    Text(
                        text = dismissButtonText,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                }
            }
        } else {
            null
        },
        containerColor = MaterialTheme.colorScheme.surface,
        titleContentColor = MaterialTheme.colorScheme.onSurface,
        textContentColor = MaterialTheme.colorScheme.onSurfaceVariant,
        shape = MaterialTheme.shapes.large
    )
}

/**
 * Reusable Warning Dialog Component for displaying warnings
 */
@Composable
fun WarningDialog(
    title: String = "Warning",
    message: String,
    onDismiss: () -> Unit,
    confirmButtonText: String = "Proceed",
    dismissButtonText: String = "Cancel",
    onConfirm: () -> Unit,
    isDismissible: Boolean = true
) {
    AlertDialog(
        onDismissRequest = {
            if (isDismissible) {
                onDismiss()
            }
        },
        title = {
            Text(
                text = title,
                color = MaterialTheme.colorScheme.onSurface,
                fontWeight = FontWeight.Bold
            )
        },
        text = {
            Text(
                text = message,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )
        },
        confirmButton = {
            TextButton(
                onClick = {
                    onConfirm()
                    onDismiss()
                }
            ) {
                Text(
                    text = confirmButtonText,
                    color = MaterialTheme.colorScheme.error,
                    fontWeight = FontWeight.Bold
                )
            }
        },
        dismissButton = {
            TextButton(
                onClick = onDismiss
            ) {
                Text(
                    text = dismissButtonText,
                    color = MaterialTheme.colorScheme.onSurfaceVariant
                )
            }
        },
        containerColor = MaterialTheme.colorScheme.surface,
        titleContentColor = MaterialTheme.colorScheme.onSurface,
        textContentColor = MaterialTheme.colorScheme.onSurfaceVariant,
        shape = MaterialTheme.shapes.large
    )
}

/**
 * Reusable Info Dialog Component for displaying information
 */
@Composable
fun InfoDialog(
    title: String = "Information",
    message: String,
    onDismiss: () -> Unit,
    buttonText: String = "OK",
    isDismissible: Boolean = true
) {
    ErrorDialog(
        title = title,
        message = message,
        onDismiss = onDismiss,
        confirmButtonText = buttonText,
        isDismissible = isDismissible
    )
}

package com.cloudsbay.brewbyadarsh.features.auth.data

import com.cloudsbay.brewbyadarsh.core.SessionManager
import com.cloudsbay.brewbyadarsh.features.auth.domain.AuthRepository
import com.cloudsbay.brewbyadarsh.features.auth.domain.models.AuthResult
import com.cloudsbay.brewbyadarsh.features.auth.domain.models.AuthSession
import com.cloudsbay.brewbyadarsh.features.auth.domain.models.AuthUser
import io.github.jan.supabase.auth.Auth
import io.github.jan.supabase.auth.providers.builtin.Email
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.withContext
import javax.inject.Inject

class AuthRepositoryImpl @Inject constructor(
    private val auth: Auth,
    private val sessionManager: SessionManager
) : AuthRepository {

    override suspend fun getSession(): AuthResult<AuthSession?> = withContext(Dispatchers.IO) {
        try {
            val session = sessionManager.authSession.first()
            AuthResult.Success(session)
        } catch (e: Exception) {
            AuthResult.Error(e, "Failed to get session: ${e.message}")
        }
    }

    override suspend fun signUp(email: String, password: String): AuthResult<AuthUser> =
        withContext(Dispatchers.IO) {
            try {
                auth.signUpWith(Email) {
                    this.email = email
                    this.password = password
                }

                val user = auth.currentUserOrNull()
                val session = auth.currentSessionOrNull()

                if (session == null && user != null) {
                    // Sign up successful but email verification required
                    AuthResult.UserVerificationRequired("Please check your email to verify your account.")
                } else if (user != null) {
                    val authUser = AuthUser(
                        id = user.id,
                        email = user.email,
                        phone = user.phone,
                        emailConfirmedAt = user.emailConfirmedAt?.toString(),
                        phoneConfirmedAt = user.phoneConfirmedAt?.toString(),
                        lastSignInAt = user.lastSignInAt?.toString(),
                        userMetadata = user.userMetadata?.mapValues { it.value.toString() },
                        appMetadata = user.appMetadata?.mapValues { it.value.toString() }
                    )
                    AuthResult.Success(authUser)
                } else {
                    AuthResult.Error(Exception("Sign up failed"), "User not created")
                }
            } catch (e: Exception) {
                AuthResult.Error(e, "Sign up failed: ${e.message}")
            }
        }

    override suspend fun signIn(email: String, password: String): AuthResult<AuthSession> =
        withContext(Dispatchers.IO) {
            try {
                auth.signInWith(Email) {
                    this.email = email
                    this.password = password
                }
                val supabaseSession = auth.currentSessionOrNull() ?: throw Exception("Session is null after sign in")

                val user = AuthUser(
                    id = supabaseSession.user?.id ?: "",
                    email = supabaseSession.user?.email,
                    phone = supabaseSession.user?.phone,
                    emailConfirmedAt = supabaseSession.user?.emailConfirmedAt?.toString(),
                    phoneConfirmedAt = supabaseSession.user?.phoneConfirmedAt?.toString(),
                    lastSignInAt = supabaseSession.user?.lastSignInAt?.toString(),
                    userMetadata = supabaseSession.user?.userMetadata?.mapValues { it.value.toString() },
                    appMetadata = supabaseSession.user?.appMetadata?.mapValues { it.value.toString() }
                )

                val authSession = AuthSession(
                    accessToken = supabaseSession.accessToken,
                    refreshToken = supabaseSession.refreshToken,
                    user = user,
                    expiresAt = supabaseSession.expiresAt.toEpochMilliseconds()
                )

                sessionManager.saveSession(authSession)
                AuthResult.Success(authSession)
            } catch (e: Exception) {
                AuthResult.Error(e, "Sign in failed: ${e.message}")
            }
        }

    override suspend fun signInWithOAuth(provider: String): AuthResult<AuthSession> =
        withContext(Dispatchers.IO) {
            try {
                AuthResult.Error(
                    Exception("OAuth not yet configured"),
                    "OAuth sign in is not available yet. Please use email/password."
                )
            } catch (e: Exception) {
                AuthResult.Error(e, "OAuth sign in failed: ${e.message}")
            }
        }

    override suspend fun signOut(): AuthResult<Unit> = withContext(Dispatchers.IO) {
        try {
            auth.signOut()
            sessionManager.clearSession()
            AuthResult.Success(Unit)
        } catch (e: Exception) {
            AuthResult.Error(e, "Sign out failed: ${e.message}")
        }
    }

    override suspend fun resetPassword(email: String): AuthResult<Unit> =
        withContext(Dispatchers.IO) {
            try {
                AuthResult.Success(Unit)
            } catch (e: Exception) {
                AuthResult.Error(e, "Password reset failed: ${e.message}")
            }
        }

    override suspend fun updatePassword(password: String): AuthResult<Unit> =
        withContext(Dispatchers.IO) {
            try {
                AuthResult.Success(Unit)
            } catch (e: Exception) {
                AuthResult.Error(e, "Password update failed: ${e.message}")
            }
        }

    override suspend fun updateUserMetadata(metadata: Map<String, String>): AuthResult<AuthUser> =
        withContext(Dispatchers.IO) {
            try {
                val dummyUser = AuthUser(
                    id = "dummy-id",
                    email = null,
                    phone = null,
                    emailConfirmedAt = null,
                    phoneConfirmedAt = null,
                    lastSignInAt = null,
                    userMetadata = metadata,
                    appMetadata = null
                )
                AuthResult.Success(dummyUser)
            } catch (e: Exception) {
                AuthResult.Error(e, "Update user metadata failed: ${e.message}")
            }
        }

    override suspend fun getCurrentUser(): AuthResult<AuthUser?> = withContext(Dispatchers.IO) {
        try {
            val user = sessionManager.authSession.first()?.user
            AuthResult.Success(user)
        } catch (e: Exception) {
            AuthResult.Error(e, "Failed to get current user: ${e.message}")
        }
    }

    override suspend fun refreshSession(): AuthResult<AuthSession> =
        withContext(Dispatchers.IO) {
            try {
                val dummyUser = AuthUser(
                    id = "dummy-id",
                    email = null,
                    phone = null,
                    emailConfirmedAt = null,
                    phoneConfirmedAt = null,
                    lastSignInAt = null,
                    userMetadata = null,
                    appMetadata = null
                )
                val dummySession = AuthSession(
                    accessToken = "dummy-token",
                    refreshToken = "dummy-refresh",
                    user = dummyUser,
                    expiresAt = null
                )
                AuthResult.Success(dummySession)
            } catch (e: Exception) {
                AuthResult.Error(e, "Session refresh failed: ${e.message}")
            }
        }

    override suspend fun verifyOtp(email: String, token: String, type: String): AuthResult<AuthSession> =
        withContext(Dispatchers.IO) {
            try {
                AuthResult.Error(
                    Exception("OTP verification not configured"),
                    "OTP verification is not available yet."
                )
            } catch (e: Exception) {
                AuthResult.Error(e, "OTP verification failed: ${e.message}")
            }
        }

    override suspend fun resendVerificationEmail(email: String): AuthResult<Unit> =
        withContext(Dispatchers.IO) {
            try {
                AuthResult.Success(Unit)
            } catch (e: Exception) {
                AuthResult.Error(e, "Resend verification email failed: ${e.message}")
            }
        }

    override fun observeAuthState(): Flow<AuthUser?> {
        return sessionManager.authSession.map { it?.user }
    }

    override suspend fun isAuthenticated(): Boolean = withContext(Dispatchers.IO) {
        sessionManager.isLoggedIn.first()
    }

    override suspend fun getAccessToken(): String? = withContext(Dispatchers.IO) {
        sessionManager.authSession.first()?.accessToken
    }
}

package com.cloudsbay.brewbyadarsh.features.auth.data

import com.cloudsbay.brewbyadarsh.core.SessionManager
import com.cloudsbay.brewbyadarsh.features.auth.domain.AuthRepository
import com.cloudsbay.brewbyadarsh.features.auth.domain.models.AuthResult
import com.cloudsbay.brewbyadarsh.features.auth.domain.models.AuthSession
import com.cloudsbay.brewbyadarsh.features.auth.domain.models.AuthUser
import io.github.jan.supabase.auth.Auth
import io.github.jan.supabase.auth.providers.builtin.Email
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.withContext
import javax.inject.Inject

import com.cloudsbay.brewbyadarsh.core.errors.AuthAction
import com.cloudsbay.brewbyadarsh.core.errors.AuthErrorMapper

class AuthRepositoryImpl @Inject constructor(
    private val auth: Auth,
    private val sessionManager: SessionManager
) : AuthRepository {

    override suspend fun getSession(): AuthResult<AuthSession?> = withContext(Dispatchers.IO) {
        try {
            tryCompletePendingSignOut()
            val session = sessionManager.authSession.first()
            AuthResult.Success(session)
        } catch (e: Exception) {
            val appError = AuthErrorMapper.map(e, AuthAction.GET_SESSION)
            AuthResult.Error(e, appError.message)
        }
    }

    override suspend fun signUp(email: String, password: String): AuthResult<AuthUser> =
        withContext(Dispatchers.IO) {
            try {
                tryCompletePendingSignOut()
                auth.signUpWith(Email) {
                    this.email = email
                    this.password = password
                }

                val user = auth.currentUserOrNull()
                val session = auth.currentSessionOrNull()

                if (session == null && user != null) {
                    // Sign up successful but email verification required
                    AuthResult.UserVerificationRequired("Please check your email to verify your account.")
                } else if (user != null) {
                    val authUser = AuthUser(
                        id = user.id,
                        email = user.email,
                        phone = user.phone,
                        emailConfirmedAt = user.emailConfirmedAt?.toString(),
                        phoneConfirmedAt = user.phoneConfirmedAt?.toString(),
                        lastSignInAt = user.lastSignInAt?.toString(),
                        userMetadata = user.userMetadata?.mapValues { it.value.toString() },
                        appMetadata = user.appMetadata?.mapValues { it.value.toString() }
                    )
                    AuthResult.Success(authUser)
                } else {
                    val appError = AuthErrorMapper.map(Exception("User not created"), AuthAction.SIGN_UP)
                    AuthResult.Error(Exception("Sign up failed"), appError.message)
                }
            } catch (e: Exception) {
                val appError = AuthErrorMapper.map(e, AuthAction.SIGN_UP)
                AuthResult.Error(e, appError.message)
            }
        }

    override suspend fun signIn(email: String, password: String): AuthResult<AuthSession> =
        withContext(Dispatchers.IO) {
            try {
                tryCompletePendingSignOut()
                auth.signInWith(Email) {
                    this.email = email
                    this.password = password
                }
                val supabaseSession = auth.currentSessionOrNull() ?: throw Exception("Session is null after sign in")

                val user = AuthUser(
                    id = supabaseSession.user?.id ?: "",
                    email = supabaseSession.user?.email,
                    phone = supabaseSession.user?.phone,
                    emailConfirmedAt = supabaseSession.user?.emailConfirmedAt?.toString(),
                    phoneConfirmedAt = supabaseSession.user?.phoneConfirmedAt?.toString(),
                    lastSignInAt = supabaseSession.user?.lastSignInAt?.toString(),
                    userMetadata = supabaseSession.user?.userMetadata?.mapValues { it.value.toString() },
                    appMetadata = supabaseSession.user?.appMetadata?.mapValues { it.value.toString() }
                )

                if (user.emailConfirmedAt == null) {
                    return@withContext AuthResult.UserVerificationRequired(
                        "Please verify your email to continue."
                    )
                }

                val authSession = AuthSession(
                    accessToken = supabaseSession.accessToken,
                    refreshToken = supabaseSession.refreshToken,
                    user = user,
                    expiresAt = supabaseSession.expiresAt.toEpochMilliseconds()
                )

                sessionManager.saveSession(authSession)
                AuthResult.Success(authSession)
            } catch (e: Exception) {
                val errorMessage = (e.message ?: "").lowercase()
                if (errorMessage.contains("email not confirmed") || errorMessage.contains("email not verified")) {
                    return@withContext AuthResult.UserVerificationRequired(
                        "Please verify your email to continue."
                    )
                }
                val appError = AuthErrorMapper.map(e, AuthAction.SIGN_IN)
                AuthResult.Error(e, appError.message)
            }
        }

    override suspend fun signInWithOAuth(provider: String): AuthResult<AuthSession> =
        withContext(Dispatchers.IO) {
            try {
                AuthResult.Error(
                    Exception("OAuth not yet configured"),
                    "OAuth sign in is not available yet. Please use email/password."
                )
            } catch (e: Exception) {
                val appError = AuthErrorMapper.map(e, AuthAction.SIGN_IN)
                AuthResult.Error(e, appError.message)
            }
        }

    override suspend fun signOut(): AuthResult<Unit> = withContext(Dispatchers.IO) {
        try {
            var remoteSucceeded = false
            try {
                auth.signOut()
                remoteSucceeded = true
            } catch (_: Exception) {
                // Remote logout can fail offline; local sign-out should still proceed.
            }
            if (!remoteSucceeded) {
                sessionManager.markPendingSignOut()
            } else {
                sessionManager.clearPendingSignOut()
            }
            sessionManager.clearSession()
            AuthResult.Success(Unit)
        } catch (e: Exception) {
            val appError = AuthErrorMapper.map(e, AuthAction.SIGN_OUT)
            AuthResult.Error(e, appError.message)
        }
    }

    override suspend fun resetPassword(email: String): AuthResult<Unit> =
        withContext(Dispatchers.IO) {
            try {
                AuthResult.Success(Unit)
            } catch (e: Exception) {
                val appError = AuthErrorMapper.map(e, AuthAction.RESET_PASSWORD)
                AuthResult.Error(e, appError.message)
            }
        }

    override suspend fun updatePassword(password: String): AuthResult<Unit> =
        withContext(Dispatchers.IO) {
            try {
                AuthResult.Success(Unit)
            } catch (e: Exception) {
                val appError = AuthErrorMapper.map(e, AuthAction.UPDATE_PASSWORD)
                AuthResult.Error(e, appError.message)
            }
        }

    override suspend fun updateUserMetadata(metadata: Map<String, String>): AuthResult<AuthUser> =
        withContext(Dispatchers.IO) {
            try {
                val dummyUser = AuthUser(
                    id = "dummy-id",
                    email = null,
                    phone = null,
                    emailConfirmedAt = null,
                    phoneConfirmedAt = null,
                    lastSignInAt = null,
                    userMetadata = metadata,
                    appMetadata = null
                )
                AuthResult.Success(dummyUser)
            } catch (e: Exception) {
                val appError = AuthErrorMapper.map(e, AuthAction.UPDATE_PROFILE)
                AuthResult.Error(e, appError.message)
            }
        }

    override suspend fun getCurrentUser(): AuthResult<AuthUser?> = withContext(Dispatchers.IO) {
        try {
            val user = sessionManager.authSession.first()?.user
            AuthResult.Success(user)
        } catch (e: Exception) {
            val appError = AuthErrorMapper.map(e, AuthAction.GET_SESSION)
            AuthResult.Error(e, appError.message)
        }
    }

    override suspend fun refreshSession(): AuthResult<AuthSession> =
        withContext(Dispatchers.IO) {
            try {
                tryCompletePendingSignOut()
                val supabaseSession = auth.currentSessionOrNull()
                    ?: throw Exception("No active session")

                val user = AuthUser(
                    id = supabaseSession.user?.id ?: "",
                    email = supabaseSession.user?.email,
                    phone = supabaseSession.user?.phone,
                    emailConfirmedAt = supabaseSession.user?.emailConfirmedAt?.toString(),
                    phoneConfirmedAt = supabaseSession.user?.phoneConfirmedAt?.toString(),
                    lastSignInAt = supabaseSession.user?.lastSignInAt?.toString(),
                    userMetadata = supabaseSession.user?.userMetadata?.mapValues { it.value.toString() },
                    appMetadata = supabaseSession.user?.appMetadata?.mapValues { it.value.toString() }
                )

                val authSession = AuthSession(
                    accessToken = supabaseSession.accessToken,
                    refreshToken = supabaseSession.refreshToken,
                    user = user,
                    expiresAt = supabaseSession.expiresAt.toEpochMilliseconds()
                )

                sessionManager.saveSession(authSession)
                AuthResult.Success(authSession)
            } catch (e: Exception) {
                val appError = AuthErrorMapper.map(e, AuthAction.REFRESH_SESSION)
                AuthResult.Error(e, appError.message)
            }
        }

    override suspend fun verifyOtp(email: String, token: String, type: String): AuthResult<AuthSession> =
        withContext(Dispatchers.IO) {
            try {
                AuthResult.Error(
                    Exception("OTP verification not configured"),
                    "OTP verification is not available yet."
                )
            } catch (e: Exception) {
                val appError = AuthErrorMapper.map(e, AuthAction.VERIFY_OTP)
                AuthResult.Error(e, appError.message)
            }
        }

    override suspend fun resendVerificationEmail(email: String): AuthResult<Unit> =
        withContext(Dispatchers.IO) {
            try {
                AuthResult.Success(Unit)
            } catch (e: Exception) {
                val appError = AuthErrorMapper.map(e, AuthAction.RESEND_VERIFICATION)
                AuthResult.Error(e, appError.message)
            }
        }

    override fun observeAuthState(): Flow<AuthUser?> {
        return sessionManager.authSession.map { it?.user }
    }

    override suspend fun isAuthenticated(): Boolean = withContext(Dispatchers.IO) {
        sessionManager.isLoggedIn.first()
    }

    override suspend fun getAccessToken(): String? = withContext(Dispatchers.IO) {
        sessionManager.authSession.first()?.accessToken
    }

    private suspend fun tryCompletePendingSignOut() {
        if (!sessionManager.isPendingSignOut()) return
        try {
            auth.signOut()
            sessionManager.clearPendingSignOut()
        } catch (_: Exception) {
            // Still offline or server unreachable; keep flag for later.
        }
    }
}

