            is AuthResult.Error -> throw Exception(result.message)
            is AuthResult.Loading -> throw Exception("Auth is loading")
        }
    }

    private suspend fun makeApiCallWithToken(token: String): ApiResponse {
        // Make API call with token in Authorization header
        // Authorization: Bearer $token
