@Composable
fun EmailVerificationScreen(
    viewModel: AuthViewModel,
    userEmail: String,
    onVerificationComplete: () -> Unit,
    onNavigateBack: () -> Unit
) {
    val uiState by viewModel.uiState.collectAsStateWithLifecycle()

    LaunchedEffect(Unit) {
        while (isActive && !uiState.isAuthenticated) {
            viewModel.checkEmailVerification()
            delay(4000)
        }
    }

    LaunchedEffect(uiState.authUser) {
        if (uiState.authUser?.emailConfirmedAt != null && uiState.isAuthenticated) {
            onVerificationComplete()
        }
    }

    EmailVerificationContent(
        userEmail = userEmail,
        isLoading = uiState.isLoading,
        error = uiState.error,
        onRetry = { viewModel.clearError() },
        onNavigateBack = onNavigateBack,
        onManualCheck = { viewModel.checkEmailVerification() }
    )
}

@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
fun EmailVerificationContent(
    userEmail: String,
    isLoading: Boolean = false,
    error: String? = null,
    onRetry: () -> Unit = {},
    onNavigateBack: () -> Unit = {},
    onManualCheck: () -> Unit = {}
) {
    var showErrorDialog by remember { mutableStateOf(false) }

    LaunchedEffect(error) {
        if (error != null) {
            showErrorDialog = true
        }
    }

    if (showErrorDialog && error != null) {
        ErrorDialog(
            title = "Verification Error",
            message = error,
            onDismiss = {
                showErrorDialog = false
                onRetry()
            },
            confirmButtonText = "Try Again"
        )
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(MaterialTheme.colorScheme.surface)
    ) {
        Box(
            modifier = Modifier
                .align(Alignment.TopEnd)
                .size(200.dp)
                .background(
                    MaterialTheme.colorScheme.primary.copy(alpha = 0.1f),
                    shape = MaterialShapes.Cookie7Sided.toShape()
                )
        )

        Column(
            modifier = Modifier
                .fillMaxSize()
                .verticalScroll(rememberScrollState())
                .padding(24.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Top
        ) {
            IconButton(
                onClick = onNavigateBack,
                modifier = Modifier
                    .align(Alignment.Start)
                    .size(40.dp)
            ) {
                Icon(
                    Icons.AutoMirrored.Filled.ArrowBack,
                    contentDescription = "Back",
                    tint = MaterialTheme.colorScheme.onSurface
                )
            }

            Spacer(modifier = Modifier.height(24.dp))

            // Email Icon
            Icon(
                imageVector = Icons.Filled.MailOutline,
                contentDescription = "Email Verification",
                modifier = Modifier.size(80.dp),
                tint = MaterialTheme.colorScheme.primary
            )

            Spacer(modifier = Modifier.height(32.dp))

            // Title
            Text(
                text = "Verify your email",
                style = MaterialTheme.typography.displaySmall,
                color = MaterialTheme.colorScheme.onSurface,
                textAlign = TextAlign.Center
            )

            Spacer(modifier = Modifier.height(16.dp))

            // Subtitle
            Text(
                text = "Please check your email",
                style = MaterialTheme.typography.bodyLarge,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                textAlign = TextAlign.Center
            )

            Spacer(modifier = Modifier.height(16.dp))

            // Email Address
            Text(
                text = userEmail,
                style = MaterialTheme.typography.bodyMedium,
                color = MaterialTheme.colorScheme.primary,
                textAlign = TextAlign.Center,
                modifier = Modifier
                    .fillMaxWidth()
                    .background(
                        MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.3f),
                        shape = MaterialTheme.shapes.medium
                    )
                    .padding(12.dp)
            )

            Spacer(modifier = Modifier.height(32.dp))

            // Instructions
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(
                        MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f),
                        shape = MaterialTheme.shapes.medium
                    )
                    .padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                Text(
                    text = "What's next?",
                    style = MaterialTheme.typography.labelLarge,
                    color = MaterialTheme.colorScheme.onSurface
                )

                VerificationStep(number = "1", description = "Check the verification email")
                VerificationStep(number = "2", description = "Click the link in the email")
                VerificationStep(number = "3", description = "Return to complete setup")
            }

            Spacer(modifier = Modifier.height(32.dp))

            // Note about spam folder
            Text(
                text = " Tip: Don't see it? Check your spam or junk folder.",
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                textAlign = TextAlign.Center,
                modifier = Modifier.padding(horizontal = 8.dp)
            )

            Spacer(modifier = Modifier.weight(1f))

            // Buttons
            Column(
                modifier = Modifier.fillMaxWidth(),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                Button(
                    onClick = onManualCheck,
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(48.dp),
                    enabled = !isLoading,
                    colors = ButtonDefaults.buttonColors(
                        containerColor = MaterialTheme.colorScheme.primary
                    ),
                    shape = MaterialTheme.shapes.medium
                ) {
                    if (isLoading) {
                        Text("Checking...")
                    } else {
                        Text("I've Verified My Email", style = MaterialTheme.typography.labelLarge)
                    }
                }

                TextButton(
                    onClick = onNavigateBack,
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        "Back to Sign Up",
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                }
            }

            Spacer(modifier = Modifier.height(24.dp))
        }
    }
}

@Composable
private fun VerificationStep(number: String, description: String) {
    Box(
        modifier = Modifier.fillMaxWidth(),
        contentAlignment = Alignment.CenterStart
    ) {
        Icon(
            imageVector = Icons.Filled.CheckCircle,
            contentDescription = null,
            modifier = Modifier
                .size(20.dp)
                .align(Alignment.CenterStart),
            tint = MaterialTheme.colorScheme.primary
        )

        Text(
            text = "$number. $description",
            style = MaterialTheme.typography.bodySmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
            modifier = Modifier.padding(start = 32.dp)
        )
    }
}

