@Composable
fun SignUpScreen(
    viewModel: AuthViewModel,
    onSignUpSuccess: () -> Unit,
    onNavigateToEmailVerification: (String) -> Unit,
    onNavigateToLogin: () -> Unit
) {
    val uiState by viewModel.uiState.collectAsStateWithLifecycle()

    LaunchedEffect(uiState.hasUnverifiedEmail) {
        if (uiState.hasUnverifiedEmail && uiState.unverifiedUserEmail != null) {
            onNavigateToEmailVerification(uiState.unverifiedUserEmail)
        }
    }

    LaunchedEffect(uiState.authUser) {
        if (uiState.authUser != null && !uiState.isLoading && uiState.message == null && !uiState.hasUnverifiedEmail) {
            onSignUpSuccess()
        }
    }

    SignUpContent(
        uiState = uiState,
        onSignUp = viewModel::signUp,
        onNavigateToLogin = onNavigateToLogin,
        onClearError = viewModel::clearError
    )
}

