package com.cloudsbay.brewbyadarsh.navigation

import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.hilt.navigation.compose.hiltViewModel
import androidx.navigation.NavHostController
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import com.cloudsbay.brewbyadarsh.features.auth.presentation.AuthViewModel
import com.cloudsbay.brewbyadarsh.features.auth.presentation.ForgotPasswordScreen
import com.cloudsbay.brewbyadarsh.features.auth.presentation.LoginScreen
import com.cloudsbay.brewbyadarsh.features.auth.presentation.SignUpScreen
import com.cloudsbay.brewbyadarsh.features.auth.presentation.WelcomeScreen
import com.cloudsbay.brewbyadarsh.features.home.presentation.HomeScreen
import kotlinx.serialization.Serializable

// Auth Routes
@Serializable
object Login

@Serializable
object SignUp

@Serializable
object ForgotPassword

@Serializable
object Welcome

// App Routes
@Serializable
object Home

@Serializable
data class Details(val id: String)

@Composable
fun BrewNavHost(
    navController: NavHostController,
    modifier: Modifier = Modifier
) {
    NavHost(
        navController = navController,
        startDestination = Login,
        modifier = modifier
    ) {
        composable<Login> {
            val authViewModel: AuthViewModel = hiltViewModel()
            LoginScreen(
                viewModel = authViewModel,
                onLoginSuccess = {
                    navController.navigate(Home) {
                        popUpTo(Login) { inclusive = true }
                    }
                },
                onNavigateToSignUp = {
                    navController.navigate(SignUp)
                },
                onNavigateToForgotPassword = {
                    navController.navigate(ForgotPassword)
                },
                onNavigateBack = {
                    navController.popBackStack()
                }
            )
        }
        composable<SignUp> {
            val authViewModel: AuthViewModel = hiltViewModel()
            SignUpScreen(
                viewModel = authViewModel,
                onSignUpSuccess = {
                    navController.navigate(Home) {
                        popUpTo(SignUp) { inclusive = true }
                    }
                },
                onNavigateToLogin = {
                    navController.popBackStack()
                }
            )
        }
        composable<ForgotPassword> {
            val authViewModel: AuthViewModel = hiltViewModel()
            ForgotPasswordScreen(
                viewModel = authViewModel,
                onNavigateToLogin = {
                    navController.popBackStack()
                }
            )
        }
        composable<Welcome> {
            val authViewModel: AuthViewModel = hiltViewModel()
            WelcomeScreen(
                viewModel = authViewModel,
                onNavigateToHome = {
                    navController.navigate(Home) {
                        popUpTo(Welcome) { inclusive = true }
                    }
                },
                onNavigateToProfile = {
                    // TODO: Navigate to profile
                }
            )
        }
        composable<Home> {
            val authViewModel: AuthViewModel = hiltViewModel()
            HomeScreen(
                authViewModel = authViewModel,
                onNavigateToLogin = {
                    navController.navigate(Login) {
                        popUpTo(Home) { inclusive = true }
                    }
                }
            )
        }
        composable<Details> {
            // Details Screen
        }
    }
}

package com.cloudsbay.brewbyadarsh.navigation

import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.hilt.navigation.compose.hiltViewModel
import androidx.navigation.NavHostController
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import com.cloudsbay.brewbyadarsh.features.auth.presentation.AuthViewModel
import com.cloudsbay.brewbyadarsh.features.auth.presentation.EmailVerificationScreen
import com.cloudsbay.brewbyadarsh.features.auth.presentation.ForgotPasswordScreen
import com.cloudsbay.brewbyadarsh.features.auth.presentation.LoginScreen
import com.cloudsbay.brewbyadarsh.features.auth.presentation.SignUpScreen
import com.cloudsbay.brewbyadarsh.features.auth.presentation.WelcomeScreen
import com.cloudsbay.brewbyadarsh.features.home.presentation.HomeScreen
import kotlinx.serialization.Serializable

// Auth Routes
@Serializable
object Login

@Serializable
object SignUp

@Serializable
data class EmailVerification(val email: String)

@Serializable
object ForgotPassword

@Serializable
object Welcome

// App Routes
@Serializable
object Home

@Serializable
data class Details(val id: String)

@Composable
fun BrewNavHost(
    navController: NavHostController,
    modifier: Modifier = Modifier
) {
    NavHost(
        navController = navController,
        startDestination = Login,
        modifier = modifier
    ) {
        composable<Login> {
            val authViewModel: AuthViewModel = hiltViewModel()
            LoginScreen(
                viewModel = authViewModel,
                onLoginSuccess = {
                    navController.navigate(Welcome) {
                        popUpTo(Login) { inclusive = true }
                    }
                },
                onNavigateToEmailVerification = { email ->
                    navController.navigate(EmailVerification(email)) {
                        popUpTo(Login) { inclusive = false }
                    }
                },
                onNavigateToSignUp = {
                    navController.navigate(SignUp)
                },
                onNavigateToForgotPassword = {
                    navController.navigate(ForgotPassword)
                },
                onNavigateBack = {
                    navController.popBackStack()
                }
            )
        }
        composable<SignUp> {
            val authViewModel: AuthViewModel = hiltViewModel()
            SignUpScreen(
                viewModel = authViewModel,
                onSignUpSuccess = {
                    navController.navigate(Welcome) {
                        popUpTo(SignUp) { inclusive = true }
                    }
                },
                onNavigateToEmailVerification = { email ->
                    navController.navigate(EmailVerification(email)) {
                        popUpTo(SignUp) { inclusive = false }
                    }
                },
                onNavigateToLogin = {
                    navController.popBackStack()
                }
            )
        }
        composable<EmailVerification> { backStackEntry ->
            val authViewModel: AuthViewModel = hiltViewModel()
            val email = backStackEntry.arguments?.getString("email") ?: ""
            EmailVerificationScreen(
                viewModel = authViewModel,
                userEmail = email,
                onVerificationComplete = {
                    navController.navigate(Welcome) {
                        popUpTo(EmailVerification::class) { inclusive = true }
                    }
                },
                onNavigateBack = {
                    navController.popBackStack()
                }
            )
        }
        composable<ForgotPassword> {
            val authViewModel: AuthViewModel = hiltViewModel()
            ForgotPasswordScreen(
                viewModel = authViewModel,
                onNavigateToLogin = {
                    navController.popBackStack()
                }
            )
        }
        composable<Welcome> {
            val authViewModel: AuthViewModel = hiltViewModel()
            WelcomeScreen(
                viewModel = authViewModel,
                onNavigateToHome = {
                    navController.navigate(Home) {
                        popUpTo(Welcome) { inclusive = true }
                    }
                },
                onNavigateToProfile = {
                    // TODO: Navigate to profile
                }
            )
        }
        composable<Home> {
            val authViewModel: AuthViewModel = hiltViewModel()
            HomeScreen(
                authViewModel = authViewModel,
                onNavigateToLogin = {
                    navController.navigate(Login) {
                        popUpTo(Home) { inclusive = true }
                    }
                }
            )
        }
        composable<Details> {
            // Details Screen
        }
    }
}
